(()=>{const f=document.querySelector('[data-r26-planner]');if(!f)return;let cat,value;const v=f.elements.vertical,t=f.elements.tier,i=f.elements.interval,out=f.querySelector('[data-r26-output]'),fv=f.querySelector('[data-r26-first-value]'),copy=f.querySelector('[data-r26-copy]'),email=f.querySelector('[data-r26-email]');const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const render=()=>{if(!cat||!value)return;const row=cat.verticals.find(x=>x.id===v.value),tier=t.value,interval=i.value;let regular,founding,annualSave=0,priceHtml;if(tier==='ENTERPRISE'){regular=interval==='ANNUAL'?row.enterprise.annualStartingUsd:row.enterprise.monthlyStartingUsd;priceHtml=`<div><span>Starting price</span><strong>${money(regular)}</strong><small>${interval==='ANNUAL'?'per year':'per month'} · written quote required</small></div>`}else{const tr=row.tiers.find(x=>x.id===tier);regular=interval==='ANNUAL'?tr.annualUsd:tr.monthlyUsd;founding=Math.round(regular*.7*100)/100;annualSave=tr.annualSavingsUsd;priceHtml=`<div><span>Regular V2</span><strong>${money(regular)}</strong><small>${interval==='ANNUAL'?'per year':'per month'}</small></div><div><span>Founding30 estimate</span><strong>${money(founding)}</strong><small>${interval==='ANNUAL'?'first year':'each of first 12 months'}</small></div><div><span>Annual plan value</span><strong>${interval==='ANNUAL'?money(annualSave):'Available'}</strong><small>12 months for price of 10</small></div>`}out.innerHTML=`<h2>${row.name} · ${tier[0]+tier.slice(1).toLowerCase()}</h2><div class="r26-price-grid">${priceHtml}</div><p>Membership improves eligible profile and growth tools; it does not buy factual accuracy, endorsement, organic rank or guaranteed results.</p>`;const steps=value.firstValueByTier[tier];fv.innerHTML='<h2>First-value path</h2><ol>'+steps.map(x=>`<li>${x}</li>`).join('')+'</ol>';const price=tier==='ENTERPRISE'?`Quote required; starting ${money(regular)} ${interval.toLowerCase()}.`:`Regular ${money(regular)} ${interval.toLowerCase()}; Founding30 estimate ${money(founding)}.`;const msg=`Franklin Navigator founding-member conversation\nCategory: ${row.name}\nLevel: ${tier}\nBilling preference: ${interval}\n${price}\nFirst value: ${steps.join('; ')}\nNo charge or guaranteed result is represented.`;f.dataset.message=msg;email.href='mailto:community@franklinnavigator.com?subject='+encodeURIComponent('Franklin founding-member conversation')+'&body='+encodeURIComponent(msg)};Promise.all([fetch('/data/membership-checkout-catalog.json').then(r=>r.json()),fetch('/data/r26-first-value.json').then(r=>r.json())]).then(([c,x])=>{cat=c;value=x;c.verticals.forEach(x=>v.add(new Option(x.name,x.id)));render()}).catch(()=>out.textContent='Planner data is temporarily unavailable. Contact community@franklinnavigator.com.');f.addEventListener('change',render);copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(f.dataset.message||'');copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy conversation',1500)}catch{copy.textContent='Copy unavailable'}})})();
